import { cache } from 'react'

// Server Components need absolute URLs; relative paths like '/api/analytics' fail to parse
const baseUrl = process.env.API_BASE_URL ?? 'http://localhost:3000'

type Analytics = { pageViews: number; visitors: number }
type Notification = { id: number; message: string }
type Settings = { theme: string; language: string }

// Parallel data fetching, wrapped in cache() so a preload and the render share one request
const getDashboardData = cache(async () => {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then((r) => r.json()) as Promise<Analytics>,
      fetch(`${baseUrl}/api/notifications`).then((r) => r.json()) as Promise<Notification[]>,
      fetch(`${baseUrl}/api/settings`).then((r) => r.json()) as Promise<Settings>,
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { pageViews: 5000, visitors: 1200 },
      notifications: [{ id: 1, message: 'Welcome to your dashboard' }],
      settings: { theme: 'light', language: 'en' },
    }
  }
})

// Call before other blocking work so these requests don't wait on it
export function preloadDashboardData() {
  void getDashboardData()
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Page views: {analytics.pageViews}</p>
        <p>Visitors: {analytics.visitors}</p>
      </section>

      <section>
        <h3>Notifications ({notifications.length})</h3>
        <ul>
          {notifications.map((n) => (
            <li key={n.id}>{n.message}</li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Language: {settings.language}</p>
      </section>
    </div>
  )
}

